CREATE TABLE `subscriptions` ( `id` INT NOT NULL AUTO_INCREMENT , `name` VARCHAR(155) NULL DEFAULT NULL , `period` INT NULL DEFAULT NULL , `price` DOUBLE NULL DEFAULT NULL , `description` VARCHAR(255) NULL DEFAULT NULL , `status` TINYINT NOT NULL DEFAULT '1' COMMENT '1=>Active, 0=>Inactive' , `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP , `updated_at` TIMESTAMP NULL DEFAULT NULL , `deleted_at` TIMESTAMP NULL DEFAULT NULL , PRIMARY KEY (`id`)) ENGINE = InnoDB;

CREATE TABLE `subscribers` ( `id` INT NOT NULL AUTO_INCREMENT , `user_id` INT(11) NULL DEFAULT NULL , `subscription_id` INT(11) NULL DEFAULT NULL , `subscribed_on` TIMESTAMP NULL DEFAULT NULL , `payment_date` TIMESTAMP NULL DEFAULT NULL , `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP , `updated_at` TIMESTAMP NULL DEFAULT NULL , `deleted_at` TIMESTAMP NULL DEFAULT NULL , PRIMARY KEY (`id`)) ENGINE = InnoDB;
ALTER TABLE `subscribers` ADD `status` TINYINT NOT NULL DEFAULT '1' COMMENT '1=>Active, 0=>Inactive' AFTER `payment_date`;